  'plans.faqCancelAnswer': 'Gói của bạn vẫn hoạt động đến hết thời gian đã thanh toán. Sau đó, bạn trở về gói miễn phí. Hình ảnh và video vượt quá 15GB sẽ được giữ lại thêm 30 ngày để bạn tải xuống.',
  'plans.faqHowFamily': 'Gói Pro hoạt động như thế nào?',
  'plans.faqHowFamilyAnswer': 'Bạn có thể thêm tối đa 4 người trong gia đình. Tất cả chia sẻ 500GB lưu trữ và nhận tất cả quyền lợi từ Chatyy One. Mỗi người có không gian riêng tư — không ai thấy tệp của người khác.',
  'plans.faqChangePlanAnswer': 'Có! Nếu bạn nâng cấp từ Plus lên Pro, chỉ tính phần chênh lệch. Nếu hạ cấp, gói hiện tại vẫn hoạt động đến hết thời gian.',
  'plans.faqCardDeclined': 'Thẻ của tôi bị từ chối, tôi phải làm gì?',
  'plans.faqCardDeclinedAnswer': 'Bạn có 7 ngày để cập nhật thẻ. Trong thời gian này, tất cả quyền lợi của bạn vẫn hoạt động. Sau 7 ngày, gói sẽ trở về miễn phí.',
  'plans.faqDataSafe': 'Dữ liệu của tôi có an toàn không?',
  'plans.faqDataSafeAnswer': 'Có! Dữ liệu thanh toán của bạn được xử lý bằng mã hóa đầu cuối. Chúng tôi không lưu số thẻ của bạn — chỉ lưu 4 chữ số cuối để bạn tham khảo.',
